<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $labels = ['sponsor' => 'Patrocinador', 'supporter' => 'Apoiador', 'organizer' => 'Organizador']; ?>
<section class="page-stack"><div class="section-heading"><div><p class="eyebrow">Portal do campeonato</p><h1>Parceiros e organizadores</h1><p class="muted">A seção só aparece publicamente quando houver parceiros ativos.</p></div><a class="button secondary" href="<?= $e(App\Core\Config::url('/admin/campeonatos/' . $championship['slug'])) ?>">Voltar ao campeonato</a></div><?php foreach (($errors ?? []) as $error): ?><p class="alert"><?= $e($error) ?></p><?php endforeach; ?><?php if (!empty($message)): ?><p class="success"><?= $e($message) ?></p><?php endif; ?><article class="panel"><h2>Novo parceiro</h2><form method="post" enctype="multipart/form-data" action="<?= $e(App\Core\Config::url('/admin/campeonatos/' . $championship['slug'] . '/parceiros')) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><label>Tipo <select name="partner_type"><?php foreach ($labels as $key => $label): ?><option value="<?= $key ?>"><?= $label ?></option><?php endforeach; ?></select></label><label>Nome <input name="name" required></label><label>Site <input name="website_url" type="url" placeholder="https://"></label><label>Logo <input name="logo" type="file" accept=".png,.jpg,.jpeg,.webp"></label><label>Ordem <input name="display_order" type="number" min="1" value="1"></label><label>Status <select name="status"><option value="active">Ativo</option><option value="inactive">Inativo</option></select></label><button type="submit">Adicionar</button></form></article><div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Nome</th><th>Site</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= $e($labels[$item['partner_type']] ?? $item['partner_type']) ?></td><td><strong><?= $e($item['name']) ?></strong></td><td><?= $item['website_url'] ? '<a href="' . $e($item['website_url']) . '" rel="noopener noreferrer" target="_blank">Abrir</a>' : '-' ?></td><td><?= $e($item['status']) ?></td><td><form method="post" action="<?= $e(App\Core\Config::url('/admin/campeonatos/' . $championship['slug'] . '/parceiros/' . $item['id'] . '/excluir')) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><button class="button secondary" type="submit">Remover</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
